    class Node:
        def __init__(self, value):#, next=None):
            self.value = value
            self.next = None

    def __init__(self):
        self.head = None
        self.count = 0

    def isEmpty(self):
        if self.count == 0:
            return True
        return False

    def push(self, value):
        node = self.Node(value)
        node.next = self.head
        self.head = node
        self.count += 1

