### Instruction:
Write a code to implement an LRU (Least Recently Used) cache.

### Response:
class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = {}
        self.lru = list()

    # get an item from the cache and update its timestamp
    def get(self, key):
        if key in self.cache:
            self.lru.remove(key)
            self.lru.append(key)
            return self.cache[key]
        else:
            return -1

    # add a new item to the cache, discard the least recently used item if cache is full 
    def put(self, key, value):
        if len(self.cache) >= self.capacity:
            self.cache.pop(self.lru[0])
            self.lru.pop(0)
        if key in self.cache: 
            self.lru.remove(key)
        self.cache[key] = value
        self.lru.append(key)

### Instruction:
Implement a stack data structure using linked lists.

### Response:
class Node:
	def __init__(self, data):
		self.data = data
		self.next = None

class Stack:
	def __init__(self):
		self.head = None
		self.num_elements = 0

	def push(self, element):
		new_node = Node(element)
		if self.head == None:
			self.head = new_node
		else:
			new_node.next = self.head
			self.head = new_node
		self.num_elements += 1

	def pop(self):
		if self.is_empty():
			return None
		temp = self.head
		self.head = self.head.next
		self.num_elements -= 1
		return temp.data

	def is_empty(self):
		if self.num_elements == 0:
			return True
		return False

	def top(self):
		if self.head:
			return self.head.data
		return None

