        rnd = np.random.RandomState(994584855)
        self.array = rnd.random(size=size).astype(dtype)
        self.dataout = np.full_like(self.array, 0.5)

    def time_clip(self, dtype, size):
        np.clip(self.array, 0.125, 0.875, self.dataout)


