### Instruction:
Design a data structure to find the first and last occurrence of a number in an array.

### Input:
array = [1, 5, 7, 8, 8, 10]

### Response:
class FindFirstLastOccurrence:
    def __init__(self, arr):
        self.arr = arr
        self.first_occurrence = -1
        self.last_occurrence = -1

    def findFirstLastOccurrence(self, k):
        #Find the first occurrence
        left = 0
        right = len(self.arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if self.arr[mid] == k and (mid == 0 or self.arr[mid-1] < k):
                self.first_occurrence = mid
                break
            elif self.arr[mid] < k:
                left = mid+1
            else:
                right = mid-1
        #Find the last occurrence
        left = 0
        right = len(self.arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if self.arr[mid] == k and (mid == len(self.arr)-1 or self.arr[mid+1] > k):
                self.last_occurrence = mid
                break
            elif self.arr[mid] > k:
                right = mid-1
            else:
                left = mid+1

        return self.first_occurrence, self.last_occurrence

if __name__ == "__main__":
