### Input:
[1, 10, 4, 2, 5, 3, 9]

### Response:
public class ArraySort { 
    public static void main(String[] args) 
    { 
        int array[] = {1, 10, 4, 2, 5, 3, 9}; 

        int n = array.length; 

        for (int i = 0; i < n-1; i++) 
            for (int j = 0; j < n-i-1; j++) 
                if (array[j] < array[j+1]) { 
                    int temp = array[j]; 
                    array[j] = array[j+1]; 
                    array[j+1] = temp; 
                } 

        for (int i=0; i<n; ++i) 
            System.out.println(array[i] + " "); 
    } 
}

