            elif i == ')' or i == ']' or i == '}':
                if len(s) > 0 and (
                (i == ')' and s[len(s)-1] == '(')or 
                (i == ']' and s[len(s)-1] == '[')or 
                (i == '}' and s[len(s)-1] == '{')):
                    s.pop()
                else:
                    return False
        return len(s) == 0

