public class Fibonacci {
    public static int[] getFibonacciNumbers(int numTerms) { 
        int[] sequence = new int[numTerms]; 
        int firstTerm = 0, secondTerm = 1;		 
        sequence[0] = firstTerm; 
        sequence[1] = secondTerm; 

        for (int i = 2; i < numTerms; i++) {
            sequence[i] = firstTerm + secondTerm; 
            int temp = secondTerm; 
            secondTerm = firstTerm + secondTerm; 
            firstTerm = temp; 
        } 
        return sequence; 
    } 

    public static void main(String[] args) 
    { 
        int numTerms = 4; 
        int[] sequence = getFibonacciNumbers(numTerms); 
        System.out.println("The first " + numTerms + " Fibonacci Numbers are:");
