def largest_prime_factor(n):

    """
    This function takes a positive integer 'n' as input and returns the largest prime factor of 'n'.
    A prime number is a number greater than 1 that is divisible only by 1 and itself.

    Example:
    largest_prime_factor(45) -> 5
    largest_prime_factor(13195) -> 29
    """

### Solution:


    # Check if the given number is divisible by 2
    while n % 2 == 0:
        n /= 2
        if n == 1:
            return 2

    # Check for all odd numbers starting from 3
    i = 3
    while i * i <= n:
        if n % i == 0:
            n /= i
        else:
            i += 2

    return int(n)

